const founderSection = "<section class=\"founder\"><div class=\"wrap\"><div class=\"founder-grid\"><div class=\"founder-card\"><div class=\"founder-img\"><img src=\"gaurav.jpg\" alt=\"Gaurav Bansal\"></div><div class=\"founder-bottom\"><div class=\"name\">Gaurav Bansal <span class=\"verified\">✔ Verified</span></div><div class=\"role\">Founder & CEO, AMG Venture Partners</div><a href=\"https://www.linkedin.com/in/gauravbansalventurecapital/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"linkedin-icon\">in</a> </div></div><div class=\"founder-content\"><div class=\"kicker\">• MEET THE FOUNDER</div><h2 class=\"h2\">I am Gaurav Bansal, <span>VC, operator, and founder</span></h2><ul class=\"founder-points\"><li><strong>14+ years</strong> of experience in venture capital, angel investing, investment banking, and technology consulting</li><li>Member of <strong>450+</strong> global angel investor syndicates</li><li><strong>50+</strong> tech startup investments</li><li><strong>35+</strong> venture capital portfolio companies</li><li>Investment banking deals worth <strong>$2Bn+</strong></li><li>Reviewed <strong>20k+</strong> pitch decks & financial models; conducted <strong>100+</strong> due diligence processes</li><li><strong>1000+</strong> mentor hours with founders globally</li></ul><div class=\"about-stats\"><div class=\"about-stat\"><div class=\"num\">3,000+</div><div class=\"lbl\">mentoring hours delivered</div></div><div class=\"about-stat\"><div class=\"num\">130+</div><div class=\"lbl\">founder workshops led</div></div><div class=\"about-stat\"><div class=\"num\">35+</div><div class=\"lbl\">VC portfolio companies</div></div></div><div class=\"about-eco\">— Expert-in-Residence / Evaluator at:</div><div class=\"about-eco-list\">Foresight Canada · Communitech · Volta · VentureLAB · Invest Nova Scotia · MassChallenge (US/LATAM) · Medtech Innovator ·  EIT Raw Materials · Catalist (LATAM) · D2XCEL (EU) · Spark Centre · YSpace</div><a href=\"https://www.linkedin.com/in/gauravbansalventurecapital/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-green\">View LinkedIn Profile</a></div></div></div></section>";
const aboutSection = "<section id=\"about\" class=\"about\"><div class=\"wrap\"><h2>About AMG Venture Partners</h2><p>AMG Venture Partners is a global business consulting and technology product firm operating across the North American and European markets. We partner with incubators, accelerators, and founders (pre-seed to Series A globally) to deliver high-quality investment-readiness content and fundraising services to tech startup CEOs. We also partner directly with startup CEOs on everything fundraising.</p><p>AMG stands for Gaurav's family, where A, M, and G are the initials for the names of his father, mother, and himself.</p><p>His parents' support and motivation have played a key role in his journey from being born in a small tier 3 town in India, pursuing education, working for 10+ years in corporates and Family office VC funds, and then taking the uncertain, risky entrepreneurial route to founding AMG Venture Partners.</p><h4>What We Do</h4><ul><li>Program design, delivery, KPI tracking & reporting for incubators/accelerators</li><li>Lead Mentor / EIR for startup CEOs</li><li>Review panelist for startup applications</li><li>Prepare startups for fundraising & investor pitching</li><li>Investment readiness workshops (cohort-based)</li><li>Review technical grant applications</li><li>Stakeholder partnerships with CEOs, investors, etc.</li></ul><h4>Founder Background</h4><p>Gaurav is a tech investor and advisor with a portfolio of 35+ VC investments across 10 countries and experience in US$2Bn+ worth of IPOs, M&A, and private equity deals. He is the founder & CEO at AMG Venture Partners, where he manages his family investment portfolio (50+ startups and member of 520+ global angel syndicates) and supports founders on investment readiness & fundraising. Additionally, he serves as an Expert in Residence and Mentor across startup programs in North America, Europe, and LATAM, and specializes in investment readiness, AI/ML strategy, and global expansion.</p><h4>Clients</h4><ul><li>Worked with 15+ accelerators across US, Canada, LATAM, and EU markets, delivering 120+ programs</li><li>Supported 125+ CEOs across AI/ML, fintech, robotics, healthtech, and more</li><li>Growth driven through founder network and word-of-mouth expansion</li></ul></div></section>";
const heroSection = "<section class=\"hero-section\"> <div class=\"hero-grid\"> <!-- LEFT --> <div class=\"hero-left\"> <h1 class=\"hero-title\"> Stop guessing <br /> what investors want. <br /> Get <span>Investment-Ready.</span> </h1> <p class=\"hero-text\"> Investment readiness is the critical bridge between a great product and a fundable company. It is the rigorous process of translating your vision into the language of venture capital—turning weak positioning and fragile financials into a defensible, institutional-grade fundraising strategy. </p> <div class=\"hero-buttons\"> <a href=\"#\" class=\"btn-primary\"> Find your track → </a> <a href=\"#\" class=\"btn-outline\"> Compare tracks </a> </div> </div> <!-- RIGHT --> <div class=\"hero-right\"> <!-- CARD 1 --> <div class=\"track-card track-1\"> <div class=\"track-top\"> <div class=\"track-icon\"> ◎ </div> <div> <div class=\"track-label\"> TRACK 1 </div> <h3>  Build Your Investor Foundation </h3> </div> </div> <div class=\"track-line\"></div> <p> For founders validating their idea and learning how venture fundraising actually works before raising capital. </p> </div> <!-- CARD 2 --> <div class=\"track-card track-2\"> <div class=\"track-top\"> <div class=\"track-icon\"> ◫ </div> <div> <div class=\"track-label\"> TRACK 2 </div> <h3> Investor Readiness Accelerator </h3> </div> </div> <div class=\"track-line\"></div> <p> For startups with traction preparing for an institutional raise and improving positioning, materials, and investor confidence. </p> </div> <!-- CARD 3 --> <div class=\"track-card track-3\"> <div class=\"track-top\"> <div class=\"track-icon\"> ◉ </div> <div> <div class=\"track-label\"> TRACK 3 </div> <h3> Fundraising Execution Partner </h3> </div> </div> <div class=\"track-line\"></div> <p> For investor-ready founders who need strategic outreach, investor targeting, meeting prep, and fundraising execution support. </p> </div> </div> </div> </section>";
const stats="<section class=\"trust-bar\"> <div class=\"wrap-trust\"> <div class=\"trust-stats\"> <div class=\"tstat\"> <span class=\"num\">$2 Bn+</span> <span class=\"lbl\">In IB Fundraising Deals</span> </div> <div class=\"tstat\"> <span class=\"num\">$200 Mn+</span> <span class=\"lbl\">Raised</span> </div> <div class=\"tstat\"> <span class=\"num\">20,000+</span> <span class=\"lbl\">Startups Reviewed</span> </div> <div class=\"tstat\"> <span class=\"num\">50+</span> <span class=\"lbl\">Angel Investments (pre-seed → series A)</span> </div> <div class=\"tstat\"> <span class=\"num\">350+</span> <span class=\"lbl\">Global Angel Syndicates</span> </div> <div class=\"tstat\"> <span class=\"num\">250+</span> <span class=\"lbl\">Startups Mentored</span> </div> </div> </div> </section>";
const pageHtml = "<!-- ========================= PREMIUM HEADER ========================= --> <nav class=\"nav\"> <!-- TOP HEADER --> <div class=\"nav-top\"> <!-- LOGO --> <a href=\"#\" class=\"brand\" data-action=\"home\"> <img src=\"logo.png\" alt=\"AMG Venture Partners\" class=\"brand-logo\" /> <div class=\"brand-copy\"> <div class=\"logo-main\"> AMG </div> <div class=\"logo-sub\"> VENTURE PARTNERS </div>  </div> </a> <!-- CENTER TITLE --> <div class=\"brand-program\"> <span>INVESTMENT READINESS PROGRAM</span> <div class=\"program-line\"></div> </div> </div> <!-- FLOATING MENU --> <div class=\"nav-menu\"> <div class=\"nav-links\"> <a href=\"#\" data-track=\"t1\">Track 1</a> <a href=\"#\"data-track=\"t2\">Track 2</a> <a href=\"#\" data-track=\"t3\">Track 3</a> <a href=\"#\"data-action=\"matrix\">Compare</a> <a href=\"https://amgventurepartners.vercel.app/\" target=\"_blank\" rel=\"noopener noreferrer\">Services</a> <a href=\"#\"data-track=\"about\">About Us</a> <a href=\"#\" class=\"menu-btn\" data-action=\"applyPage\"> Apply Now </a> </div> </div> </nav>\n\n<!-- =================== LANDING =================== -->\n<div id=\"landing\" class=\"page\">\n\n"+ heroSection + stats +" <!-- PAIN -->\n  <section class=\"problem\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— The Fundraising Reality</div>\n        <h2 class=\"h2\">Most startups don’t fail at fundraising because the idea is bad.</h2>\n        <p class=\"section-sub\">Investors pass because the narrative is unclear, the positioning is weak, the traction story lacks conviction, or the founder starts outreach before the business is truly fundable. Most rejections happen long before the pitch call ends.</p>\n      </div>\n      <div class=\"pain-grid\">\n        <div class=\"pain\"><div class=\"pain-no\">01</div><div class=\"pain-q\">\"Am I building a venture-scale business or just a good product?\"</div><p>Most founders confuse product quality with venture fundability. Investors care about market size, timing, scalability, defensibility, and return potential.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">02</div><div class=\"pain-q\">\"Investors like the idea — but nobody moves forward\"</div><p>Interest is not conviction. Most decks explain the product but fail to explain why this becomes a large venture-scale company.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">03</div><div class=\"pain-q\">\"How much should I raise? At what valuation?\"</div><p>You downloaded an Excel template, picked a number, and now you're not sure if it's defensible.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">04</div><div class=\"pain-q\">\"I sent hundreds of investor emails. Nothing happened.\"</div><p>I sent hundreds of investor emails. Nothing happened.You bought a list. You sent the same teaser to everyone. The list isn't the problem , the system is.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">05</div><div class=\"pain-q\">\"They sent a SAFE — what do I sign?\"</div><p>Liquidation preferences, MFN, board seats, valuation caps. One wrong clause costs you $500K in dilution.</p></div>\n        <div class=\"pain\"><div class=\"pain-no\">06</div><div class=\"pain-q\">\"I'm ready. I just need investors.\"</div><p>Your kit is solid. Your traction is real. You don't need a course — you need access and execution.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"why-raise-fails\"> <div class=\"wrap\"> <div class=\"section-head\"> <div class=\"kicker\"> — Why Most Raises Stall </div> <h2 class=\"h2\"> Investors usually decide long before due diligence begins. </h2> <p class=\"section-sub\"> Most early-stage founders think fundraising failure happens because they need a better deck or more investor meetings. In reality, investors pass because the company does not yet look venture-backable. </p> </div> <div class=\"fails-grid\"> <div class=\"fail-card\"> <div class=\"fail-no\">01</div> <h3> Weak Positioning </h3> <p> Investors cannot quickly understand why this startup wins, why now is the right market timing, or why this becomes a large venture-scale company. </p> </div> <div class=\"fail-card\"> <div class=\"fail-no\">02</div> <h3> Unclear Narrative </h3> <p> Founders explain features and product workflows, but fail to communicate market conviction, defensibility, and long-term upside. </p> </div> <div class=\"fail-card\"> <div class=\"fail-no\">03</div> <h3> Premature Outreach </h3> <p> Many startups start emailing investors before their deck, traction story, financial model, or fundraising strategy are truly ready. </p> </div> <div class=\"fail-card\"> <div class=\"fail-no\">04</div> <h3> Lack of Investor Psychology </h3> <p> Fundraising is not just storytelling. It is understanding how investors evaluate risk, market size, timing, and return potential. </p> </div> </div> </div> </section> \n\n "+ founderSection +" <!-- TRACK SELECTOR -->\n  <section class=\"tracks-intro\" id=\"tracks\">\n    <div class=\"wrap\">\n      <div class=\"section-head\" >\n        <div class=\"kicker\" >— Three Tracks. One Outcome.</div>\n        <h2 class=\"h2\">Three stages. Three different fundraising problems.</h2>\n        <p class=\"section-sub\" style=\"margin-right:auto\">Whether you are figuring out if you are venture-fundable, preparing for a raise, or actively pursuing investors — each track is built for a specific fundraising stage.</p>\n      </div>\n    </div>\n    <div class=\"wrap\">\n      <div class=\"tracks-grid\">\n\n        <div class=\"track-card t1\">\n          <div class=\"track-num\">Track 01 · Foundation</div>\n          <h3 class=\"track-name\">Build Your Investor Foundation</h3>\n          <p class=\"track-tag\">For founders still validating the business and learning how venture fundraising actually works before raising capital.</p>\n          <div class=\"track-meta\">\n            <div><div class=\"tmeta-l\">Stage</div><div class=\"tmeta-v\">Pre-MVP / Idea</div></div>\n            <div><div class=\"tmeta-l\">Format</div><div class=\"tmeta-v\">8-Wk Cohort</div></div>\n            <div><div class=\"tmeta-l\">Cohort Size</div><div class=\"tmeta-v\">10–15 founders</div></div>\n            <div><div class=\"tmeta-l\">Channel</div><div class=\"tmeta-v\">Group · Virtual</div></div>\n          </div>\n          <ul class=\"track-bullets\">\n            <li>All 6 program modules taught live</li>\n            <li>Weekly group workshops + office hours</li>\n            <li>Mock VC diligence drill at week 6</li>\n            <li>Cohort demo day with real angels/VCs</li>\n            <li>1:1 fundraising roadmap session</li>\n            <li>Walk away with full investor kit</li>\n          </ul>\n          <div class=\"track-price\">$1,497 <small>+ HST</small></div>\n          <a href=\"#\" class=\"track-cta\" data-track=\"t1\">Explore Track 1 <span>→</span></a>\n        </div>\n\n        <div class=\"track-card t2\">\n          <div class=\"track-num\">Track 02 · Accelerator</div>\n          <h3 class=\"track-name\">Investor Readiness Accelerator</h3>\n          <p class=\"track-tag\">For startups with traction preparing for an institutional raise and needing sharper positioning, stronger materials, and investor-level feedback.</p>\n          <div class=\"track-meta\">\n            <div><div class=\"tmeta-l\">Stage</div><div class=\"tmeta-v\">Post-MVP + Traction</div></div>\n            <div><div class=\"tmeta-l\">Format</div><div class=\"tmeta-v\">6-Wk Hybrid</div></div>\n            <div><div class=\"tmeta-l\">Cohort Size</div><div class=\"tmeta-v\">8–10 founders</div></div>\n            <div><div class=\"tmeta-l\">Channel</div><div class=\"tmeta-v\">Cohort + 1:1</div></div>\n          </div>\n          <ul class=\"track-bullets\">\n            <li>Compressed curriculum delivered fast</li>\n            <li>3 dedicated 1:1 feedback sessions</li>\n            <li>Mock investor demo day (real panel)</li>\n            <li>2 VC feedback sessions with practicing investors</li>\n            <li>Investor outreach toolkit + warm intro pathway</li>\n            <li>Application-based — vetted cohort</li>\n          </ul>\n          <div class=\"track-price\">$2,997 <small>+ HST</small></div>\n          <a href=\"#\" class=\"track-cta\" data-track=\"t2\">Explore Track 2 <span>→</span></a>\n        </div>\n\n        <div class=\"track-card t3\">\n          <div class=\"track-num\">Track 03 · Outreach</div>\n          <h3 class=\"track-name\">Fundraising Execution Partner</h3>\n          <p class=\"track-tag\">For investor-ready founders who need strategic outreach, investor targeting, meeting preparation, and fundraising execution support.</p>\n          <div class=\"track-meta\">\n            <div><div class=\"tmeta-l\">Stage</div><div class=\"tmeta-v\">Investor-Ready</div></div>\n            <div><div class=\"tmeta-l\">Format</div><div class=\"tmeta-v\">3-Mo 1:1 Engagement</div></div>\n            <div><div class=\"tmeta-l\">Spots</div><div class=\"tmeta-v\">Selective · Rolling</div></div>\n            <div><div class=\"tmeta-l\">Channel</div><div class=\"tmeta-v\">1:1 Done-With-You</div></div>\n          </div>\n          <ul class=\"track-bullets\">\n            <li>Kit audit + investor-readiness sign-off</li>\n            <li>50–100 vetted target investors built for you</li>\n            <li>Outreach setup + ambassador army activation</li>\n            <li>Weekly meeting prep + post-meeting debriefs</li>\n            <li>Term-sheet review & negotiation coaching</li>\n            <li>Partner-licensed broker-dealer compliant</li>\n          </ul>\n          <div class=\"track-price\">From $6,000 <small>+ HST · 3 fee structures</small></div>\n          <a href=\"#\" class=\"track-cta\" data-track=\"t3\">Explore Track 3 <span>→</span></a>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- DECISION MATRIX -->\n  <section class=\"matrix\" id=\"matrix\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Which Track Is For You?</div>\n        <h2 class=\"h2\">Six honest questions. One clear answer.</h2>\n        <p class=\"section-sub\">If you say yes to most rows in a column, that's your track. If you're between two — talk to me.</p>\n      </div>\n\n      <div class=\"matrix-table\">\n        <div class=\"matrix-row head\">\n          <div class=\"matrix-cell\">Your situation</div>\n          <div class=\"matrix-cell col-t1\">Track 01 · Foundation</div>\n          <div class=\"matrix-cell col-t2\">Track 02 · Accelerator</div>\n          <div class=\"matrix-cell col-t3\">Track 03 · Outreach</div>\n        </div>\n        <div class=\"matrix-row\">\n          <div class=\"matrix-cell q\">I have an MVP and some traction.</div>\n          <div class=\"matrix-cell tick tick-no\">Not required</div>\n          <div class=\"matrix-cell tick tick-yes\">Required</div>\n          <div class=\"matrix-cell tick tick-yes\">Required</div>\n        </div>\n        <div class=\"matrix-row\">\n          <div class=\"matrix-cell q\">My pitch deck, model & dataroom are investor-grade.</div>\n          <div class=\"matrix-cell tick tick-no\">We'll build them</div>\n          <div class=\"matrix-cell tick tick-maybe\">We'll sharpen them</div>\n          <div class=\"matrix-cell tick tick-yes\">Required</div>\n        </div>\n        <div class=\"matrix-row\">\n          <div class=\"matrix-cell q\">I'm raising in the next 3–6 months.</div>\n          <div class=\"matrix-cell tick tick-no\">Too early</div>\n          <div class=\"matrix-cell tick tick-yes\">Perfect fit</div>\n          <div class=\"matrix-cell tick tick-yes\">Now</div>\n        </div>\n        <div class=\"matrix-row\">\n          <div class=\"matrix-cell q\">I want to learn the fundraising game properly.</div>\n          <div class=\"matrix-cell tick tick-yes\">Core focus</div>\n          <div class=\"matrix-cell tick tick-yes\">Compressed</div>\n          <div class=\"matrix-cell tick tick-no\">Out of scope</div>\n        </div>\n        <div class=\"matrix-row\">\n          <div class=\"matrix-cell q\">I primarily need investor access & meetings.</div>\n          <div class=\"matrix-cell tick tick-no\">Not yet</div>\n          <div class=\"matrix-cell tick tick-maybe\">Toolkit + intros</div>\n          <div class=\"matrix-cell tick tick-yes\">Core focus</div>\n        </div>\n        <div class=\"matrix-row\">\n          <div class=\"matrix-cell q\">I want a cohort experience with peers.</div>\n          <div class=\"matrix-cell tick tick-yes\">Yes — group</div>\n          <div class=\"matrix-cell tick tick-yes\">Yes — small</div>\n          <div class=\"matrix-cell tick tick-no\">1:1 only</div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- AD-HOC SERVICES (links out) -->\n  <section class=\"adhoc\" id=\"services\">\n    <div class=\"wrap\">\n      <div class=\"adhoc-inner\">\n        <div>\n          <div class=\"kicker\">— Already in a track? Need just one piece?</div>\n          <h3>Tackle a single deliverable with à-la-carte services.</h3>\n          <p>Whether you're inside Track 1 or Track 2 and want to go deeper on one specific deliverable, or you only need one targeted piece of work — pick exactly what you need from the standalone services menu.</p>\n          <a href=https://amgventurepartners.vercel.app/ class=\"btn btn-yellow\">Browse all services <span class=\"arr\">→</span></a>\n        </div>\n        <div class=\"adhoc-list\">\n          <span>Investor Readiness Review</span>\n          <span>Pitch Deck Review</span>\n          <span>Pitch Deck Creation</span>\n          <span>Financial Model Build</span>\n          <span>Valuation Analysis</span>\n          <span>Fundraising Dynamics</span>\n          <span>Investor Q&A Prep</span>\n          <span>Cap Table Simulation</span>\n          <span>Term-Sheet Review</span>\n          <span>Ask-Me-Anything 1:1</span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- FINALE -->\n      <section class=\"finale\" id=\"finale\"> <div class=\"wrap\"> <div class=\"kicker\"> — Fundraising Starts Before Investor Outreach </div> <h2> Find out what investors will question before you start fundraising. </h2> <p> Whether you are still validating your business, preparing your investor materials, or actively planning a raise — we will help you identify the gaps, pressure-test your strategy, and determine the right fundraising path. </p> <div class=\"finale-points\"> <div class=\"fpoint\"> Investor readiness assessment </div> <div class=\"fpoint\"> Fundraising strategy review </div> <div class=\"fpoint\"> Investor narrative feedback </div> <div class=\"fpoint\"> Track recommendation based on stage </div> </div> <a href=\"#\" class=\"btn btn-yellow\" data-action=\"callPage\"> Book Your Fundraising Strategy Call <span class=\"arr\">→</span> </a> </div> </section>\n\n</div>     <div id=\"t4-page\" class=\"track-page t4-page\">\n\n  <section class=\"thero t4-hero\">\n  </section></div>\n\n\n<!-- =================== TRACK 1 PAGE =================== -->\n<div id=\"t1-page\" class=\"track-page t1-page\">\n\n  <section class=\"thero t1-hero\">\n    <div class=\"wrap\">\n      <button class=\"thero-back\" data-action=\"home\">← All Tracks</button>\n      <div class=\"thero-grid\">\n        <div>\n          <div class=\"thero-eyebrow\">Track 01 · Foundation Cohort</div>\n          <h1 class=\"thero-title\">Fundraising 101 to Investor-Ready in 8 weeks.</h1>\n          <p class=\"thero-sub\">For pre-MVP and just-launched founders 9–14 months from raising. By week 8, you'll know if you're VC-fundable, you'll have every material an investor will ask for, and you'll have pitched a real panel of angels and VCs.</p>\n          <div class=\"hero-ctas\">\n            <a href=\"#\" class=\"btn btn-primary\" data-action=\"applyPage\">Apply to next cohort <span class=\"arr\">→</span></a>\n            <a href=\"#t1-curriculum\" class=\"btn btn-ghost\">See the 8-week breakdown</a>\n          </div>\n          <div class=\"thero-meta\">\n            <div class=\"thero-mcell\"><div class=\"lbl\">Format</div><div class=\"val\">8-Week Cohort</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Delivery</div><div class=\"val\">Live · Virtual</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Cohort Size</div><div class=\"val\">10–15 founders</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Investment</div><div class=\"val\">$1,497 + HST</div></div>\n          </div>\n        </div>\n        <div class=\"thero-visual\">\n          <div class=\"visual-card\">\n            <div class=\"vc-badge\">Track 01</div>\n            <div class=\"vc-title\" style=\"margin-top:32px\">By Week 8 you'll have:</div>\n            <div class=\"vc-line\"><span class=\"l\">Investor-grade pitch deck</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">5-yr financial model</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Email teaser + dataroom</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Investor CRM</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Cap table to Series B</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Demo day pitched</span><span class=\"v\">✓</span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"duo\">\n    <div class=\"wrap\">\n      <div class=\"duo-grid\">\n        <div class=\"duo-card bad\">\n          <h3>Is this you right now?</h3>\n          <p class=\"sub\">— Be honest. Most founders are.</p>\n          <ul class=\"duo-list\">\n            <li>You have a great idea but no MVP yet, and you're not sure when to start fundraising.</li>\n            <li>You've watched 40 YouTube videos about pitch decks and you're more confused than before.</li>\n            <li>You don't know what an investor actually evaluates — or whether you're even VC-fundable.</li>\n            <li>You don't know what to charge for \"valuation,\" how much to raise, or what dilution means for you.</li>\n            <li>You feel behind. You feel underqualified. You're scared to even reach out to an investor.</li>\n          </ul>\n        </div>\n        <div class=\"duo-card good\">\n          <h3>Here's what changes.</h3>\n          <p class=\"sub\">— By the end of week 8.</p>\n          <ul class=\"duo-list\">\n            <li>You'll have a brutally honest answer to \"should I raise VC, raise angels, or bootstrap?\"</li>\n            <li>You'll have an investor-grade kit: deck, model, teaser, dataroom, CRM, Q&A bank.</li>\n            <li>You'll have pitched real angels and VCs at a cohort demo day — and have their feedback.</li>\n            <li>You'll know your funding ask, your valuation logic, your cap table 3 rounds out.</li>\n            <li>You'll have a personalized fundraising roadmap and the confidence to execute it.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 8-WEEK CURRICULUM -->\n  <section class=\"curriculum\" id=\"t1-curriculum\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— The 8-Week Sprint</div>\n        <h2 class=\"h2\">Every week ships one tangible deliverable.</h2>\n        <p class=\"section-sub\">No \"soak it in.\" No homework backlog. You leave each week with a piece of your investor kit done.</p>\n      </div>\n      <div class=\"weekly\">\n\n        <div class=\"week\">\n          <div class=\"week-num\">01<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-group\">Group Workshop · Diagnostic</div>\n            <div class=\"week-title\">Are You VC-Fundable? The Diagnostic.</div>\n            <div class=\"week-desc\">We run your business through a fundability scorecard. We map investor types to your stage. You leave knowing which path makes sense — VC, angel, grant, bootstrap — and why.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Deliverable</span><ul><li>Personal fundability scorecard</li><li>Target investor profile draft</li><li>Decision: raise or not raise</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">02<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-group\">Group Workshop · Market Dynamics</div>\n            <div class=\"week-title\">Funding Landscape, Valuations & The Math.</div>\n            <div class=\"week-desc\">Real market data on rounds, valuations, dilution. We declutter funding ask, runway, pre/post-money, target KPIs. Grants and non-dilutive options. How VCs actually value your company.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Deliverable</span><ul><li>Funding ask + runway sheet</li><li>Realistic valuation range</li><li>Grants shortlist</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">03<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-group\">Group Workshop · Financial Model</div>\n            <div class=\"week-title\">Building a Rational Financial Model.</div>\n            <div class=\"week-desc\">Why investors care, what they ignore, how to build assumptions you can defend. Revenue lines, unit economics, hiring plan, three statements, 50–100x return narrative. No Excel template guesswork.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Deliverable</span><ul><li>5-yr financial model (v1)</li><li>Investor return scenario</li><li>KPI tracker</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">04<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-group\">Group Workshop · Pitch Deck</div>\n            <div class=\"week-title\">Pitch Deck — Flow, Content, Narrative.</div>\n            <div class=\"week-desc\">What investors actually look for slide-by-slide. When and which format to share. Storytelling that works (and the kind that gets you ignored). Side-by-side: good decks vs bad decks.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Deliverable</span><ul><li>Pitch deck v1 (10–12 slides)</li><li>Verbal pitch script</li><li>Forwardable teaser</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">05<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-group\">Group Workshop · Outreach</div>\n            <div class=\"week-title\">Investor Outreach Strategy.</div>\n            <div class=\"week-desc\">Target investor profile. Building an investor CRM. Ambassador army for warm intros. Email teaser playbook. Investor meetings, Q&A, decoding feedback, follow-up cadence.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Deliverable</span><ul><li>Investor CRM (50 names)</li><li>Cold + warm outreach templates</li><li>Q&A bank v1</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">06<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-mock\">Mock Drill · Reality Check</div>\n            <div class=\"week-title\">Mock VC Diligence Drill.</div>\n            <div class=\"week-desc\">Submit your dataroom. A practicing VC tears it apart on a live call. You watch your kit get pressure-tested the way it would in a real diligence process — but in a safe room.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Deliverable</span><ul><li>Recorded diligence feedback</li><li>Dataroom gap list</li><li>Kit revisions roadmap</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">07<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-group\">Group Workshop · Legal</div>\n            <div class=\"week-title\">Investment Instruments & Term Sheets.</div>\n            <div class=\"week-desc\">SAFE vs convertible vs priced round. The dangerous clauses no one tells you about — MFN, liquidation preference, board seats, drag-along. Cap table simulation pre-seed → Series B.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Deliverable</span><ul><li>Term-sheet negotiation cheat sheet</li><li>Cap table simulation (6-yr)</li><li>Red-flag clauses checklist</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">08<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-mock\">Demo Day · Real Investors</div>\n            <div class=\"week-title\">Cohort Demo Day + 1:1 Roadmap.</div>\n            <div class=\"week-desc\">Pitch a panel of 3–5 active angels and VCs. Get structured feedback. Then we lock your personalized fundraising roadmap in a 1:1 session — when to start, what's still missing, and how to pace it.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Deliverable</span><ul><li>Demo day recording + feedback</li><li>Personalized fundraising roadmap</li><li>Final investor kit (sign-off)</li></ul></div>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- DELIVERABLES VAULT -->\n  <section class=\"vault\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— The Investor Kit Vault</div>\n        <h2 class=\"h2\">Every artifact an investor will ever ask for — built in 8 weeks.</h2>\n      </div>\n      <div class=\"vault-grid\">\n        <div class=\"vault-item\"><div class=\"ico\">01</div><h4>Pitch Deck</h4><p>Concise 10–12 slide narrative built for investor review and forwarding.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">02</div><h4>Financial Model</h4><p>Integrated five-year model showing statements, assumptions, returns, and funding scenarios.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">03</div><h4>Email Teaser</h4><p>Short forwardable teaser written to earn opens, replies, and introductions.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">04</div><h4>Dataroom</h4><p>Organized diligence folder covering core documents investors typically request quickly.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">05</div><h4>Investor CRM</h4><p>Targeted investor pipeline mapped by stage, sector, geography, and fit.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">06</div><h4>Investor Memo</h4><p>Investor brief and Q&A bank covering questions investors usually ask.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">07</div><h4>Cap Table</h4><p>Scenario-based ownership model showing dilution from pre-seed through Series B.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">08</div><h4>Term-Sheet Toolkit</h4><p>Clause-by-clause negotiation guide highlighting red flags founders should challenge.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">09</div><h4>Pitch Script</h4><p>Flexible pitch scripts tailored for short, standard, and detailed meetings.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">10</div><h4>Fundability Scorecard</h4><p>Clear fundability diagnostic showing current gaps and highest-priority fixes.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">11</div><h4>Roadmap Doc</h4><p>Stage-specific fundraising roadmap with clear timeline, milestones, and next actions.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">12</div><h4>Grants Database</h4><p>Curated list of 200+ non-dilutive grant opportunities across North America.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- LIVE COMPONENTS -->\n  <section class=\"live\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— What Makes This Different</div>\n        <h2 class=\"h2\">It's not a video course. It's live execution.</h2>\n        <p class=\"section-sub\">No pre-recorded modules you'll never finish. Every workshop is live. Every deliverable gets reviewed.</p>\n      </div>\n      <div class=\"live-grid\">\n        <div class=\"live-card\"><span class=\"pill pill-cohort\">8 × Live Workshops</span><h3>Weekly Group Workshops</h3><p>One live session per module, every week. Recorded for replay if you miss it. Real-time Q&A, real-time feedback.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-office\">Bi-weekly Office Hours</span><h3>Open Q&A Calls</h3><p>Stuck on assumptions in your model? Confused about a term-sheet clause? Open mic, 90 min, twice a month.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-mock\">Week 6 · Live Drill</span><h3>Mock VC Diligence Drill</h3><p>Real VC tears apart your dataroom on a live call. The most uncomfortable hour you'll have. Worth every second.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-mock\">Week 8 · Real Panel</span><h3>Cohort Demo Day</h3><p>Pitch 3–5 active angels and VCs. Get scored. Get feedback. For some founders, get an actual second meeting.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-1on1\">Week 8 · 1:1</span><h3>Personalized Fundraising Roadmap</h3><p>One private 60-min session at the end. We map out your raise — when to start, what to fix, how to pace it.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-cohort\">12-Mo Access</span><h3>Founder Community + Updates</h3><p>Private community of cohort alumni. Lifetime access to templates. 12-month access to all program updates.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- PRICING -->\n  <section class=\"pricing\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Investment</div>\n        <h2 class=\"h2\">One price. Everything included.</h2>\n      </div>\n      <div class=\"price-card\">\n        <div>\n          <div class=\"price-amt\">\n            $1,497\n            <small>USD + HST · per founder</small>\n               </div>\n        </div>\n        <div class=\"price-includes\">\n          <h4>— What's included</h4>\n          <ul>\n            <li>8 live group workshops (one per module)</li>\n            <li>Bi-weekly office hours (4 sessions)</li>\n            <li>Mock VC diligence drill at week 6</li>\n            <li>Cohort demo day with 3–5 real angels/VCs</li>\n            <li>1:1 fundraising roadmap session</li>\n            <li>250+ slides + 1-yr access to all module videos</li>\n            <li>All templates, tools, models — lifetime access</li>\n            <li>200+ corporate grants database</li>\n            <li>Private founder community (lifetime)</li>\n            <li>12 months of free program updates</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- AD-HOC LINK -->\n  \n\n  <!-- FAQ -->\n  <section class=\"faq\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Questions?</div>\n        <h2 class=\"h2\">Honest answers before you apply.</h2>\n      </div>\n      <div class=\"faq-list\">\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">I don't even have an MVP yet. Is this too early?<span class=\"plus\">+</span></div><div class=\"faq-a\">Track 1 is built specifically for pre-MVP and just-launched founders. The point is to learn what investors evaluate before you waste 6 months building the wrong thing. If you're 9–14 months from raising, this is the right time.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Will the cohort demo day actually get me funded?<span class=\"plus\">+</span></div><div class=\"faq-a\">No promises. Demo day is for high-quality feedback from real investors and rare second meetings — not for guaranteed checks. If you want investor outreach as the primary outcome, look at Track 2 or Track 3.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">What if I miss a live session?<span class=\"plus\">+</span></div><div class=\"faq-a\">All sessions are recorded and you have 1-year view access. But the bi-weekly office hours are where most of the real value lives — make those if you can.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Can my cofounder join too?<span class=\"plus\">+</span></div><div class=\"faq-a\">Yes. One additional cofounder seat is +$497, which gives them full community + workshop access. Fundraising is a team sport — having both founders aligned is worth it.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">What if I realize halfway through I'm not VC-fundable?<span class=\"plus\">+</span></div><div class=\"faq-a\">That's a successful outcome. Better to find out in week 2 of a cohort than 6 months into a failed raise. We'll redirect you to the right capital path — angels, grants, revenue-based financing, bootstrapping.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Is this for North America only?<span class=\"plus\">+</span></div><div class=\"faq-a\">Track 1 is open globally — the curriculum is universal. Track 3 (outreach) is currently focused on North America, Europe, UK, Middle East, and Africa.</div></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"finale\">\n    <div class=\"wrap\">\n      <h2>Apply to the next Track 1 cohort.</h2>\n      <p>Cohorts cap at 15 founders. Application is short — 5 questions, 10 minutes. We respond within 48 hours.</p>\n      <a href=\"#\" class=\"btn btn-yellow\" data-action=\"applyPage\">Start your application <span class=\"arr\">→</span></a>\n    </div>\n  </section>\n\n</div>\n\n<!-- =================== TRACK 2 PAGE =================== -->\n<div id=\"t2-page\" class=\"track-page t2-page\">\n\n  <section class=\"thero t2-hero\">\n    <div class=\"wrap\">\n      <button class=\"thero-back\" data-action=\"home\">← All Tracks</button>\n      <div class=\"thero-grid\">\n        <div>\n          <div class=\"thero-eyebrow\">Track 02 · Accelerator Cohort</div>\n          <h1 class=\"thero-title\">From Post-MVP to Term Sheet in 6 weeks.</h1>\n          <p class=\"thero-sub\">For founders with traction who plan to raise in 3–6 months. Compressed curriculum + 1:1 feedback sessions where I tear into your materials and you go execute the fixes. By week 6, your kit is investor-grade and you're ready to launch outreach yourself.</p>\n          <div class=\"hero-ctas\">\n            <a href=\"#\" class=\"btn btn-primary\" data-action=\"applyPage\">Apply to next cohort <span class=\"arr\">→</span></a>\n            <a href=\"#t2-curriculum\" class=\"btn btn-ghost\">See the 6-week sprint</a>\n          </div>\n          <div class=\"thero-meta\">\n            <div class=\"thero-mcell\"><div class=\"lbl\">Format</div><div class=\"val\">6-Wk Hybrid</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Delivery</div><div class=\"val\">Cohort + 1:1</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Cohort Size</div><div class=\"val\">8–10 founders</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Investment</div><div class=\"val\">$2,997 + HST</div></div>\n          </div>\n        </div>\n        <div class=\"thero-visual\">\n          <div class=\"visual-card\">\n            <div class=\"vc-badge\">Track 02</div>\n            <div class=\"vc-title\" style=\"margin-top:32px\">By Week 6 you'll have:</div>\n            <div class=\"vc-line\"><span class=\"l\">Investor-grade revamped deck</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Defensible valuation + ask</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Mock demo day completed</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">2 VC feedback sessions logged</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Outreach toolkit ready</span><span class=\"v\">✓</span></div>\n            <div class=\"vc-line\"><span class=\"l\">100-investor target CRM</span><span class=\"v\">✓</span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"duo\">\n    <div class=\"wrap\">\n      <div class=\"duo-grid\">\n        <div class=\"duo-card bad\">\n          <h3>Is this you right now?</h3>\n          <p class=\"sub\">— You're closer than you think. Just not converting.</p>\n          <ul class=\"duo-list\">\n            <li>You have an MVP, real users or revenue, but investors aren't biting on your deck.</li>\n            <li>You've pitched at 3 demo days, sent 80 cold emails, gotten 4 meetings — and 4 polite passes.</li>\n            <li>Your financial model has nice numbers but you can't defend a single assumption under pressure.</li>\n            <li>You don't know if your ask is too high, too low, or just wrong for your stage.</li>\n            <li>You need speed. You don't have 12 weeks to take a course. You're raising in months, not years.</li>\n          </ul>\n        </div>\n        <div class=\"duo-card good\">\n          <h3>Here's what changes.</h3>\n          <p class=\"sub\">— By the end of week 6.</p>\n          <ul class=\"duo-list\">\n            <li>Your pitch deck has been torn apart, rebuilt, and stress-tested by a real investor lens.</li>\n            <li>Your financial model defends every assumption, your ask is rational, your dilution is mapped.</li>\n            <li>You've pitched a real panel at mock demo day — and got two private 1:1 VC feedback calls.</li>\n            <li>You have an outreach toolkit (target list, teaser, CRM, intro pathway) ready to launch yourself.</li>\n            <li>You walk out fully equipped to run your own outreach with confidence.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 6-WEEK SPRINT -->\n  <section class=\"curriculum\" id=\"t2-curriculum\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— The 6-Week Sprint</div>\n        <h2 class=\"h2\">Group sessions teach. 1:1 sessions sharpen. You execute.</h2>\n        <p class=\"section-sub\">Each week you get a group strategy call + a 1:1 feedback session on a specific deliverable. I review and give you sharp, investor-lens feedback. You take it away and rebuild. The deliverable is yours — you own it.</p>\n      </div>\n      <div class=\"weekly\">\n\n        <div class=\"week\">\n          <div class=\"week-num\">01<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-group\">Group · Foundations</div>\n            <div class=\"week-title\">Fundraising Reset & Investor Lens.</div>\n            <div class=\"week-desc\">Compressed: how VCs operate, red flags, your ideal investor profile, fundraising dynamics. Day one we re-baseline what investors actually look for at your stage so the next 5 weeks have a clear north star.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">Outcome</span><ul><li>Investor profile locked</li><li>Red flag self-audit</li><li>Stage-appropriate ask range</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">02<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-1on1\">1:1 Feedback Session A</div>\n            <div class=\"week-title\">Pitch Deck Teardown.</div>\n            <div class=\"week-desc\">You send me your current deck. I review it slide-by-slide on a 60-min 1:1 call and give you concrete feedback — narrative gaps, missing slides, fluffed numbers. <strong>You go execute the rebuild.</strong> Group session covers deck principles in parallel.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Rebuilt pitch deck v2</li><li>Verbal pitch script</li><li>Forwardable teaser draft</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">03<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-1on1\">1:1 Feedback Session B</div>\n            <div class=\"week-title\">Financial Model + Ask + Valuation.</div>\n            <div class=\"week-desc\">You bring your model, ask, and valuation rationale to a 60-min 1:1. I pressure-test assumptions, dilution math, and your investor return narrative. <strong>You go rebuild the model</strong> using the feedback. Group session covers funding dynamics in parallel.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You execute</span><ul><li>Defensible financial model</li><li>Ask + valuation rationale</li><li>Cap table + dilution scenarios</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">04<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-feedback\">VC Feedback Session 1</div>\n            <div class=\"week-title\">External VC Pulse-Check.</div>\n            <div class=\"week-desc\">A pre-booked 30-min call with a practicing VC. Not a pitch — a feedback session. You get a brutally honest external perspective on your story, your numbers, and where you stand in the market. Recording included.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Recorded VC feedback</li><li>External market perspective</li><li>Revisions checklist</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">05<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-mock\">Mock Investor Demo Day</div>\n            <div class=\"week-title\">Pitch a Real Panel.</div>\n            <div class=\"week-desc\">Pitch 3–5 active angels and VCs in a structured demo day format. Q&A. Live feedback. Scored on clarity, traction, and investability. The day after, debrief in group session — what landed, what didn't.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Demo day recording</li><li>Panel scoring + feedback</li><li>Final pitch revisions</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">06<span>Week</span></div>\n          <div>\n            <div class=\"week-tag tag-1on1\">1:1 Feedback Session C</div>\n            <div class=\"week-title\">Outreach Toolkit + Launch Prep.</div>\n            <div class=\"week-desc\">Final 1:1: I review your target investor CRM, email teaser, ambassador outreach plan. We finalize your outreach toolkit. <strong>I provide the templates, target list framework, and warm-intro pathway — you run the outreach yourself.</strong> Plus: VC feedback session 2.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You leave with</span><ul><li>100-investor target CRM</li><li>Email + warm-intro templates</li><li>VC feedback #2 recording</li></ul></div>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- HOW THE 1:1 SESSIONS WORK -->\n  <section class=\"vault\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— How the 1:1 Sessions Work</div>\n        <h2 class=\"h2\">I give the feedback. You do the work.</h2>\n        <p class=\"section-sub\">This is not done-for-you. It's done-with-you, with a clear handoff every time.</p>\n      </div>\n      <div class=\"vault-grid\" style=\"grid-template-columns:repeat(4,1fr)\">\n        <div class=\"vault-item\"><div class=\"ico\">01</div><h4>You submit</h4><p>You bring the current version of the deliverable — deck, model, CRM — to the 1:1 call.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">02</div><h4>I review live</h4><p>I tear into it on the call. Investor lens. Slide-by-slide, assumption-by-assumption. Concrete, written feedback.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">03</div><h4>You execute</h4><p>You take the feedback and rebuild the deliverable yourself. The work is yours. The artifact is yours.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">04</div><h4>Async check</h4><p>Send me the rebuilt version. I sign off async or flag the last 1–2 fixes via written notes. Done.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- LIVE COMPONENTS -->\n  <section class=\"live\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— What You Get, Live</div>\n        <h2 class=\"h2\">Six weeks. Three 1:1s. Two VC calls. One demo day.</h2>\n      </div>\n      <div class=\"live-grid\">\n        <div class=\"live-card\"><span class=\"pill pill-cohort\">6 × Group Strategy Calls</span><h3>Compressed Curriculum</h3><p>One per week. The full curriculum boiled down to what matters for raising in 3–6 months. Live, recorded, no fluff.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-1on1\">3 × 1:1 Feedback Sessions</span><h3>Deck · Model · Outreach</h3><p>60 min each. I review your work, give sharp investor-lens feedback. You go rebuild. You own the output.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-feedback\">2 × VC Feedback Calls</span><h3>External Pulse-Checks</h3><p>30 min each with practicing VCs/angels. Not pitching — getting feedback. Recorded for replay.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-mock\">Week 5 · Real Panel</span><h3>Mock Investor Demo Day</h3><p>Pitch 3–5 real investors. Get scored. Get feedback. The closest thing to a real raise without one.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-launch\">Week 6 · Toolkit Handoff</span><h3>Outreach Launch Prep</h3><p>I provide the templates, the target list framework, the warm-intro pathway. You run outreach yourself.</p></div>\n        <div class=\"live-card\"><span class=\"pill pill-office\">Weekly Office Hours</span><h3>Live Q&A Throughout</h3><p>Stuck mid-week? Live office hours every week of the program for fast unblocking.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- WHAT YOU LEAVE WITH -->\n  <section class=\"curriculum\" style=\"background:var(--cream)\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Your Output</div>\n        <h2 class=\"h2\">Six weeks in. Investor-grade out.</h2>\n      </div>\n      <div class=\"vault-grid\" style=\"grid-template-columns:repeat(3,1fr)\">\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">Investor-Grade Pitch Deck</h4><p style=\"color:var(--ink-soft)\">Rebuilt by you, sharpened by me. Investor-tested at mock demo day.</p></div>\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">Defensible Financial Model</h4><p style=\"color:var(--ink-soft)\">Ask, valuation, runway, dilution — every number you can defend.</p></div>\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">Email Teaser + Forwardable Blurb</h4><p style=\"color:var(--ink-soft)\">Cold + warm versions, tested in a real outreach context.</p></div>\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">100-Investor Target CRM</h4><p style=\"color:var(--ink-soft)\">Vetted list mapped to your stage, sector, geography, and check size.</p></div>\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">Outreach Templates + Pathway</h4><p style=\"color:var(--ink-soft)\">Cold email, warm-intro framework, follow-up cadence — you run it.</p></div>\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">Investor Q&A + Memo</h4><p style=\"color:var(--ink-soft)\">Bank of 30+ questions with sharp answers and 1-pager memo.</p></div>\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">Term-Sheet Cheat Sheet</h4><p style=\"color:var(--ink-soft)\">Clauses to negotiate, perils to avoid, MFN/LP/board seat playbook.</p></div>\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">Demo Day Recording</h4><p style=\"color:var(--ink-soft)\">Your full pitch + Q&A + panel scoring, replayable forever.</p></div>\n        <div class=\"vault-item\" style=\"background:#fff;border:1px solid var(--line);color:var(--ink)\"><div class=\"ico\">→</div><h4 style=\"color:var(--teal-deep)\">2 VC Feedback Recordings</h4><p style=\"color:var(--ink-soft)\">External pulse-checks captured for ongoing reference.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- PRICING -->\n  <section class=\"pricing\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Investment</div>\n        <h2 class=\"h2\">One price. Application-based admission.</h2>\n      </div>\n      <div class=\"price-card\">\n        <div>\n          <div class=\"price-amt\">\n            $2,997\n            <small>USD + HST · per founder</small>\n                     </div>\n        </div>\n        <div class=\"price-includes\">\n          <h4>— What's included</h4>\n          <ul>\n            <li>6 live group strategy calls</li>\n            <li>3 × 1:1 feedback sessions (deck · model · outreach)</li>\n            <li>2 × external VC feedback calls (recorded)</li>\n            <li>Mock investor demo day with real panel</li>\n            <li>Weekly office hours throughout</li>\n            <li>Outreach toolkit: templates, CRM, intro pathway</li>\n            <li>All program materials + 1-yr access</li>\n            <li>200+ corporate grants database</li>\n            <li>Private founder community (lifetime)</li>\n            <li>12 months of program updates</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- AD-HOC LINK -->\n  \n\n  <!-- FAQ -->\n  <section class=\"faq\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Questions?</div>\n        <h2 class=\"h2\">Honest answers before you apply.</h2>\n      </div>\n      <div class=\"faq-list\">\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Will you build my pitch deck and model for me?<span class=\"plus\">+</span></div><div class=\"faq-a\">No. In Track 2 the 1:1 sessions are feedback sessions — I review your work, give you sharp investor-lens feedback, and you go execute the rebuild yourself. The deliverable is yours, you own it. If you want done-for-you deck or model creation, those are available as standalone à-la-carte services.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Will you do investor outreach for me?<span class=\"plus\">+</span></div><div class=\"faq-a\">No. In Track 2, week 6 is about preparing your outreach toolkit — I provide the templates, the target list framework, and the warm-intro pathway. <strong>You run the outreach yourself.</strong> If you want done-with-you outreach where I run the engine alongside you, that's Track 3.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Why is this application-based?<span class=\"plus\">+</span></div><div class=\"faq-a\">Because the cohort needs founders who are actually ready to execute. We screen for: real MVP, real traction, raising in 3–6 months, ability to commit to weekly work. Roughly 40% of applicants get in. It keeps the cohort tight.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">What's the difference vs Track 1?<span class=\"plus\">+</span></div><div class=\"faq-a\">Track 1 is 8 weeks, group-only, for pre-MVP founders learning the game. Track 2 is 6 weeks, hybrid (group + 1:1), for post-MVP founders raising soon. Track 2 has 1:1 feedback sessions and external VC feedback calls — Track 1 doesn't.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">What if mock demo day generates real investor interest?<span class=\"plus\">+</span></div><div class=\"faq-a\">It happens. We won't broker the deal (Track 3 handles that with proper licensing), but if a panel investor wants to take a follow-up meeting, you've got the contact and the green light. Track 2 alumni regularly land follow-ups from demo day panelists.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Can I move from Track 2 into Track 3?<span class=\"plus\">+</span></div><div class=\"faq-a\">Yes — and many founders do. Track 2 graduates with a polished kit are exactly the profile Track 3 looks for. Talk to me about the upgrade pathway during week 6.</div></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"finale\">\n    <div class=\"wrap\">\n      <h2>Apply to the next Track 2 cohort.</h2>\n      <p>Capped at 8–10 founders. Application takes 15 minutes — we ask about your traction, materials, and timeline. We respond within 48 hours.</p>\n      <a href=\"#\" class=\"btn btn-yellow\" data-action=\"applyPage\">Start your application <span class=\"arr\">→</span></a>\n    </div>\n  </section>\n\n</div>\n\n<!-- =================== TRACK 3 PAGE =================== -->\n<div id=\"t3-page\" class=\"track-page t3-page\">\n\n  <section class=\"thero t3-hero\">\n    <div class=\"wrap\">\n      <button class=\"thero-back\" data-action=\"home\">← All Tracks</button>\n      <div class=\"thero-grid\">\n        <div>\n          <div class=\"thero-eyebrow\">Track 03 · Done-With-You Outreach</div>\n          <h1 class=\"thero-title\">Your kit is ready. Now get in front of the right investors.</h1>\n          <p class=\"thero-sub\">For founders who are already investor-ready and need access + execution, not education. Done-with-you investor outreach over 3 months — kit audit, vetted target list, managed outreach cadence, meeting prep, and term-sheet support. Run in partnership with a registered broker-dealer for full regulatory compliance.</p>\n          <div class=\"hero-ctas\">\n            <a href=\"#\" class=\"btn btn-primary\" data-action=\"callPage\">Book a fit call <span class=\"arr\">→</span></a>\n            <a href=\"#t3-pricing\" class=\"btn btn-ghost\">See 3 fee structures</a>\n          </div>\n          <div class=\"thero-meta\">\n            <div class=\"thero-mcell\"><div class=\"lbl\">Format</div><div class=\"val\">3-Mo Engagement</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Delivery</div><div class=\"val\">1:1 Done-With-You</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Compliance</div><div class=\"val\">Broker-Dealer Partner</div></div>\n            <div class=\"thero-mcell\"><div class=\"lbl\">Spots</div><div class=\"val\">Selective · Rolling</div></div>\n          </div>\n        </div>\n        <div class=\"thero-visual\">\n          <div class=\"visual-card\">\n            <div class=\"vc-badge\">Track 03</div>\n            <div class=\"vc-title\" style=\"margin-top:32px\">Engagement Snapshot</div>\n            <div class=\"vc-line\"><span class=\"l\">Vetted target investors</span><span class=\"v\">50–100</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Engagement length</span><span class=\"v\">3 months</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Founder hours saved</span><span class=\"v\">75+ hrs</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Weekly 1:1 calls</span><span class=\"v\">Yes</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Term-sheet support</span><span class=\"v\">Included</span></div>\n            <div class=\"vc-line\"><span class=\"l\">Geographies</span><span class=\"v\">NA · EU · UK · ME · AF</span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"duo\">\n    <div class=\"wrap\">\n      <div class=\"duo-grid\">\n        <div class=\"duo-card bad\">\n          <h3>You don't need a course.</h3>\n          <p class=\"sub\">— You need access and execution.</p>\n          <ul class=\"duo-list\">\n            <li>Your pitch deck, model, and dataroom are already investor-grade. You've done the work.</li>\n            <li>You have real traction — revenue, pilots, retention numbers — that make you fundable today.</li>\n            <li>You've burned weeks on cold outreach lists that don't convert and warm intros that fizzle.</li>\n            <li>You don't have time to source 100 investors, vet them, write 100 emails, and chase follow-ups.</li>\n            <li>When term sheets land, you want someone who can read every clause and negotiate the dangerous ones out.</li>\n          </ul>\n        </div>\n        <div class=\"duo-card good\">\n          <h3>Here's the engine.</h3>\n          <p class=\"sub\">— What we run alongside you.</p>\n          <ul class=\"duo-list\">\n            <li>50–100 vetted, stage-matched target investors built specifically for your raise.</li>\n            <li>Cold outreach + warm-intro pathway managed to actually generate meetings.</li>\n            <li>Pre-meeting prep + post-meeting debriefs on every investor conversation that matters.</li>\n            <li>Term-sheet review and negotiation coaching when offers come in.</li>\n            <li>3 fee structures: pure $, $ + advisory shares, or $ + shares + success fee — pick what fits.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 6-STEP ENGINE -->\n  <section class=\"curriculum\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— The Outreach Engine</div>\n        <h2 class=\"h2\">Six steps. One outcome.</h2>\n        <p class=\"section-sub\">A systematic process that has saved founders 75+ hours and generated meetings with active investors across North America, Europe, the UK, the Middle East, and Africa.</p>\n      </div>\n      <div class=\"weekly\">\n\n        <div class=\"week\">\n          <div class=\"week-num\">01<span>Step</span></div>\n          <div>\n            <div class=\"week-tag tag-1on1\">Onboarding</div>\n            <div class=\"week-title\">Investment Readiness Review.</div>\n            <div class=\"week-desc\">We audit your current state — business hygiene, corporate structure, teaser, deck, financial model, dataroom. Sign-off: you're ready to engage. If not, we redirect you to Track 2 first. We don't take engagements that aren't fundable.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Readiness audit report</li><li>Gap-fix list (if any)</li><li>Outreach execution plan</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">02<span>Step</span></div>\n          <div>\n            <div class=\"week-tag tag-1on1\">Investor Targeting</div>\n            <div class=\"week-title\">Vetted Target Investor List.</div>\n            <div class=\"week-desc\">50–100 active investors filtered by stage, sector, geography, check size, and recent activity. Vetted with you so you approve every name. Saves 20+ hours of list-building you'd otherwise spend on databases and LinkedIn rabbit holes.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Filtered investor CRM</li><li>Investor profile briefs</li><li>Founder approval round</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">03<span>Step</span></div>\n          <div>\n            <div class=\"week-tag tag-launch\">Outreach Execution</div>\n            <div class=\"week-title\">Cold + Warm Outreach.</div>\n            <div class=\"week-desc\">Customized teaser. Ambassador army activated for warm intros. Outreach launched to the target list to generate investor meetings. Saves 10+ hours of execution time. Live CRM with response rates and meeting status.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Customized teaser</li><li>Outreach launched</li><li>Live response dashboard</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">04<span>Step</span></div>\n          <div>\n            <div class=\"week-tag tag-1on1\">Meeting Support</div>\n            <div class=\"week-title\">Pre-Meeting Prep + Debriefs.</div>\n            <div class=\"week-desc\">Before each first meeting: 30-min prep call on the specific investor, their thesis, likely questions. After: debrief, decode their feedback, plan the follow-up. Ongoing during the entire investor meeting cycle. 10+ hours saved.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Pre-meeting briefs</li><li>Live debrief calls</li><li>Follow-up templates</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">05<span>Step</span></div>\n          <div>\n            <div class=\"week-tag tag-1on1\">Diligence Q&A</div>\n            <div class=\"week-title\">Due Diligence Support.</div>\n            <div class=\"week-desc\">When investors enter diligence, we help you address every question — financial, operational, legal, technical. Your dataroom stays organized. You answer faster than 95% of founders. 8–10 hours saved.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Q&A response support</li><li>Dataroom maintenance</li><li>Diligence checklist tracking</li></ul></div>\n        </div>\n\n        <div class=\"week\">\n          <div class=\"week-num\">06<span>Step</span></div>\n          <div>\n            <div class=\"week-tag tag-mock\">Term Sheet & Close</div>\n            <div class=\"week-title\">Negotiation + Round Close.</div>\n            <div class=\"week-desc\">When term sheets land, we read every clause — valuation cap, MFN, liquidation preference, board seats, drag-along, anti-dilution. We coach you through negotiation. We help close the round. 8–10 hours saved.</div>\n          </div>\n          <div class=\"week-deliv\"><span class=\"lbl\">You receive</span><ul><li>Term-sheet review</li><li>Negotiation coaching</li><li>Round close support</li></ul></div>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- COMPLIANCE -->\n  <section class=\"vault\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Regulatory Compliance</div>\n        <h2 class=\"h2\">Run in partnership with a registered broker-dealer.</h2>\n        <p class=\"section-sub\">Securities solicitation across North America requires proper licensing. Track 3 is operated in partnership with a registered broker-dealer to keep every step of the engagement compliant — from outreach to term-sheet to round close.</p>\n      </div>\n      <div class=\"vault-grid\" style=\"grid-template-columns:repeat(3,1fr)\">\n        <div class=\"vault-item\"><div class=\"ico\">✓</div><h4>Licensed Partner</h4><p>Track 3 engagements run alongside a registered broker-dealer. Every solicitation step is compliant with applicable securities regulation.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">✓</div><h4>Transparent Fee Structures</h4><p>Three options — pure cash, cash + advisory shares, cash + shares + success fee. Documented up front. No hidden carry.</p></div>\n        <div class=\"vault-item\"><div class=\"ico\">✓</div><h4>Multi-Geography</h4><p>Operational in North America, Europe, the UK, the Middle East, and Africa. We map regulatory requirements per jurisdiction.</p></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 3 PRICING OPTIONS -->\n  <section class=\"pricing\" id=\"t3-pricing\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Three Fee Structures</div>\n        <h2 class=\"h2\">Pick the structure that fits how you want to align.</h2>\n        <p class=\"section-sub\">Same engagement scope. Different ways to share the upside. Pure cash if you prefer no equity. Cash + shares if you want lower upfront. Cash + shares + success fee if you want maximum alignment.</p>\n      </div>\n\n      <div class=\"t3-pricing\">\n\n        <div class=\"t3-price\">\n          <div class=\"opt-name\">Option 01 · Pure Cash</div>\n          <h4>The Straight Engagement.</h4>\n          <p class=\"opt-sub\">— No equity. No carry.</p>\n          <div class=\"opt-amt\">$8,000<small> USD + HST</small></div>\n          <div class=\"opt-extra\">One-time execution fee · 3-month engagement · Zero variable fees</div>\n          <ul>\n            <li>Full investment readiness review</li>\n            <li>50–100 vetted investor list</li>\n            <li>Outreach execution + ambassador army</li>\n            <li>Weekly 1:1 strategy calls</li>\n            <li>Pre-meeting prep + debriefs</li>\n            <li>Diligence Q&A support</li>\n            <li>Term-sheet review + negotiation coaching</li>\n            <li>Round close support</li>\n          </ul>\n          <a href=\"#\" class=\"btn btn-ghost\" style=\"border-color:var(--teal);width:100%;justify-content:center\">Choose Pure Cash <span class=\"arr\">→</span></a>\n        </div>\n\n        <div class=\"t3-price featured\">\n          <div class=\"pf-tag\">Most Popular</div>\n          <div class=\"opt-name\">Option 02 · Cash + Advisory Shares</div>\n          <h4>The Aligned Engagement.</h4>\n          <p class=\"opt-sub\">— Lower upfront. Skin in the game.</p>\n          <div class=\"opt-amt\">$6,000<small> USD + HST</small></div>\n          <div class=\"opt-extra\"><strong>+ Advisory shares</strong> (typical: 0.25%–0.75% vested over 24 months, negotiated per stage and round size)</div>\n          <ul>\n            <li>Everything in Option 01</li>\n            <li>Lower upfront cash outlay</li>\n            <li>Advisory shares = long-term alignment</li>\n            <li>Standard advisor agreement template</li>\n            <li>Suited for founders preserving runway</li>\n            <li>Most chosen by Series-A bound startups</li>\n          </ul>\n          <a href=\"#\" class=\"btn btn-primary\" style=\"width:100%;justify-content:center\">Choose Cash + Shares <span class=\"arr\">→</span></a>\n        </div>\n\n        <div class=\"t3-price\">\n          <div class=\"opt-name\">Option 03 · Cash + Shares + Success Fee</div>\n          <h4>The Performance Engagement.</h4>\n          <p class=\"opt-sub\">— Maximum alignment. Lowest cash.</p>\n          <div class=\"opt-amt\">$6,000<small> USD + HST</small></div>\n          <div class=\"opt-extra\"><strong>+ Advisory shares + Success fee</strong> (% of capital raised within 12 months, negotiable; reduces as raise size increases above $/€2M)</div>\n          <ul>\n            <li>Everything in Option 02</li>\n            <li>Negotiable success fee on capital raised</li>\n            <li>Excludes standalone non-dilutive grants</li>\n            <li>Includes match-funding & dilutive raises</li>\n            <li>Success fee scales down for raises &gt; $2M</li>\n            <li>Maximum alignment across all parties</li>\n          </ul>\n          <a href=\"#\" class=\"btn btn-ghost\" style=\"border-color:var(--teal);width:100%;justify-content:center\">Choose Performance <span class=\"arr\">→</span></a>\n        </div>\n\n      </div>\n\n      <div class=\"compliance\">\n        <div class=\"compliance-ico\">i</div>\n        <div>\n          <h4>About the success fee.</h4>\n          <p>Success fee applies to capital raised by the client within 12 months of engagement, from any investor and any investment instrument — excluding standalone non-dilutive government grants, but including match-funding non-dilutive or dilutive investments. The fee is negotiable for quality founding teams and decreases as fundraising amounts increase. Engagements below $/€2M are accepted on a selective basis. All fees are agreed in writing through the registered broker-dealer partner.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- AD-HOC LINK -->\n  \n\n  <!-- FAQ -->\n  <section class=\"faq\">\n    <div class=\"wrap\">\n      <div class=\"section-head\">\n        <div class=\"kicker\">— Questions?</div>\n        <h2 class=\"h2\">Honest answers before we engage.</h2>\n      </div>\n      <div class=\"faq-list\">\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Are you a registered broker-dealer?<span class=\"plus\">+</span></div><div class=\"faq-a\">Track 3 is run in partnership with a registered broker-dealer license holder to ensure full compliance with securities regulation in the jurisdictions we operate. The licensed partner handles the regulated aspects of solicitation; I run the strategy, materials, and meeting support side. All fee arrangements are documented and compliant.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">What if my kit isn't ready?<span class=\"plus\">+</span></div><div class=\"faq-a\">We won't start outreach with a flawed kit — it wastes your runway and burns investor goodwill. If the readiness audit flags major gaps, we'll redirect you to Track 2 (cohort) or specific à-la-carte services first. Then we engage. We're selective about which engagements we take.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Can you guarantee meetings or capital raised?<span class=\"plus\">+</span></div><div class=\"faq-a\">No. No legitimate fundraising partner can. What we guarantee: a vetted target list, executed outreach, prep + debrief on every meeting, term-sheet support. We take engagements where we believe the raise is viable. We don't take engagements where it isn't.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">Which fee structure should I pick?<span class=\"plus\">+</span></div><div class=\"faq-a\">If preserving runway matters most → Option 02 or 03 (lower upfront). If you want zero variable cost → Option 01. If you want maximum alignment with my upside tied to your outcome → Option 03. We'll discuss it on the fit call.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">What sectors and stages do you work with?<span class=\"plus\">+</span></div><div class=\"faq-a\">Tech startups at pre-seed through Series A primarily. Sectors I'm most active in: ClimateTech, AI/ML, Digital Health, Medical Device, Hardware, Supply Chain, Fintech. Geographies: North America, Europe, the UK, the Middle East, and Africa.</div></div>\n        <div class=\"faq-item\"><div class=\"faq-q\" data-action=\"faq\">What does \"75+ hours saved\" actually mean?<span class=\"plus\">+</span></div><div class=\"faq-a\">Concretely: 20+ hours on investor list-building, 10+ on outreach execution, 10+ on meeting prep & debriefs, 8–10 on diligence Q&A, 8–10 on term-sheet review/negotiation, plus weekly strategy support. Founders who try this alone burn the time and learn it's not the highest-leverage use of their week.</div></div>\n      </div>\n    </div>\n  </section>\n\n  ${founderSection }<section class=\"finale\">\n    <div class=\"wrap\">\n      <h2>Ready to engage?</h2>\n      <p>Track 3 starts with a 30-minute fit call. We assess readiness, walk through the 3 fee structures, and decide if it's a match. No pitch deck required for the call.</p>\n      <a href=\"#\" class=\"btn btn-yellow\" data-action=\"callPage\">Book your fit call <span class=\"arr\">→</span></a>\n    </div>\n  </section>\n\n</div>\n\n<!-- =================== FOOTER =================== -->\n<footer class=\"foot\">\n  <div class=\"wrap\">\n    <div class=\"foot-row\">\n      <div>© 2026 Investor-Ready · Run by Gaurav Bansal</div>\n      <div>Track 3 operated in partnership with a registered broker-dealer.</div>\n    </div>\n  </div>\n</footer>" +"<div id=\"about-page\" class=\"track-page about-page\">"+ aboutSection +"</div><div id=\"call-page\" class=\"track-page inquiry-page\"><section class=\"inquiry\"><div class=\"wrap\"><button class=\"thero-back\" data-action=\"home\">← Back</button><div class=\"inquiry-grid\"><div><div class=\"kicker\">Strategy Call</div><h1 class=\"thero-title\">Book your strategy call.</h1><p class=\"thero-sub\">Tell us where you are in the fundraising journey. We will review your details and get back to you with the right next step.</p></div><form class=\"inquiry-form\" id=\"strategycall\"> <input type=\"hidden\" name=\"_subject\" value=\"New strategy call request - Investment Readiness Program\"><input type=\"hidden\" name=\"_captcha\" value=\"false\">     <input type=\"hidden\" name=\"_webhook\" value=\"https://script.google.com/macros/s/AKfycbzVII_B1IctdseS9GxxbFNWBeHznGTnMbEZnCg_5R_Y9YFMPY-G252d9uR7UYaGRTtx/exec\"> <!-- helps identify which form --><input type=\"hidden\" name=\"Request type\" value=\"Strategy Call\"><label>Full name<input name=\"Full name\" required></label><label>Email<input type=\"email\" name=\"Email\" required></label><label>Company / startup name<input name=\"Company\"></label><label>Startup stage<select name=\"Startup stage\" required><option value=\"\">Select stage</option><option>Idea / Pre-MVP</option><option>MVP built</option><option>Post-MVP with traction</option><option>Investor-ready / actively raising</option></select></label><label>What do you need help with?<textarea name=\"What they need help with\" rows=\"5\" required></textarea></label><button class=\"btn btn-primary\" type=\"submit\">Send request <span class=\"arr\">→</span></button></form></div></div></section></div><div id=\"apply-page\" class=\"track-page inquiry-page\"><section class=\"inquiry\"><div class=\"wrap\"><button class=\"thero-back\" data-action=\"home\">← Back</button><div class=\"inquiry-grid\"><div><div class=\"kicker\">Application</div><h1 class=\"thero-title\">Apply to the Investment Readiness Program.</h1><p class=\"thero-sub\">Share a few details about your company, stage, and fundraising timeline. Applications are reviewed within 48 hours.</p></div><form class=\"inquiry-form\" id=\"newProgramApplication\"><input type=\"hidden\" name=\"_subject\" value=\"New program application - Investment Readiness Program\"><input type=\"hidden\" name=\"_webhook\" value=\"https://script.google.com/macros/s/AKfycbzVII_B1IctdseS9GxxbFNWBeHznGTnMbEZnCg_5R_Y9YFMPY-G252d9uR7UYaGRTtx/exec\"> <!-- helps identify which form --><input type=\"hidden\" name=\"_captcha\" value=\"false\"><input type=\"hidden\" name=\"Request type\" value=\"Program Application\"><label>Full name<input name=\"Full name\" required></label><label>Email<input type=\"email\" name=\"Email\" required></label><label>Company / startup name<input name=\"Company\" required></label><label>Which track are you interested in?<select name=\"Track interest\" required><option value=\"\">Select track</option><option>Track 1 - Foundation</option><option>Track 2 - Accelerator</option><option>Track 3 - Investor Outreach</option><option>Not sure yet</option></select></label><label>Current traction / stage<textarea name=\"Current traction or stage\" rows=\"4\" required></textarea></label><label>Fundraising timeline<textarea name=\"Fundraising timeline\" rows=\"4\" required></textarea></label><button class=\"btn btn-primary\" type=\"submit\">Submit application <span class=\"arr\">→</span></button></form></div></div></section></div>";
function scrollToId(id) {
  window.setTimeout(() => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' })
  }, 50)
}

export default function App() {
  const [page, setPage] = useState('landing')
const [showPopup, setShowPopup] = useState(false)
const [loading, setLoading] = useState(false)

const handleSubmit = async (e) => {
  e.preventDefault()
setLoading(true)
  if (loading) return

  setLoading(true)

  const submitButton = document.querySelector(
    '#customForm button[type=\"submit"]'
  )

  if (submitButton) {
    submitButton.disabled = true
    submitButton.innerHTML = 'Submitting...'
    submitButton.style.opacity = '0.7'
    submitButton.style.cursor = 'not-allowed'
  }

  const formData = new FormData(e.target)

  try {
    const response = await fetch(
      'https://formsubmit.co/ajax/manishpanda24@gmail.com',
      {
        method: 'POST',
        body: formData,
      }
    )

    const data = await response.json()

    if (data.success) {
      setShowPopup(true)
      e.target.reset()
    }
  } catch (error) {
    console.error(error)
  }



  if (submitButton) {
    submitButton.disabled = false
    submitButton.innerHTML = 'Send request →'
    submitButton.style.opacity = '1'
    submitButton.style.cursor = 'pointer'
  }
    setLoading(false)
}

useEffect(() => {
  const attachFormListeners = () => {
    const forms = document.querySelectorAll('.inquiry-form')

    forms.forEach((form) => {
      form.removeEventListener('submit', handleSubmit)
      form.addEventListener('submit', handleSubmit)
    })
  }

  const timer = setTimeout(() => {
    attachFormListeners()
  }, 500)

  return () => clearTimeout(timer)
}, [page])
  const handleClick = useCallback((event) => {
    const target = event.target
    if (!(target instanceof Element)) return

    const trackLink = target.closest('[data-track]')
    if (trackLink) {
      event.preventDefault()
      const nextPage = trackLink.getAttribute('data-track')
      setPage(nextPage)
      window.scrollTo({ top: 0, behavior: 'instant' })
      return
    }

    const actionLink = target.closest('[data-action]')
    if (actionLink) {
      const action = actionLink.getAttribute('data-action')
      event.preventDefault()

      if (action === 'faq') {
        actionLink.closest('.faq-item')?.classList.toggle('open')
        return
      }

      if (action === 'matrix') {
        setPage('landing')
        scrollToId('matrix')
        return
      }

      if (action === 'applyPage') {
        setPage('apply')
        window.scrollTo({ top: 0, behavior: 'instant' })
        return
      }

      if (action === 'callPage') {
        setPage('call')
        window.scrollTo({ top: 0, behavior: 'instant' })
        return
      }

      if (action === 'finale') {
        setPage('landing')
        scrollToId('finale')
        return
      }

      setPage('landing')
      window.scrollTo({ top: 0, behavior: 'instant' })
      return
    }

    const emptyAnchor = target.closest('a[href=\"#"]')
    if (emptyAnchor) {
      event.preventDefault()
    }
  }, [])
return (
  <>
    <main
      className="app-shell"
      data-page={page}
      onClick={handleClick}
      dangerouslySetInnerHTML={{ __html: pageHtml }}
    />
{loading && (
  <div
    style={{
      position: 'fixed',
      inset: 0,
      background: 'rgba(0,0,0,0.45)',
      backdropFilter: 'blur(4px)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 99999,
    }}
  >
    <div
      style={{
        width: '70px',
        height: '70px',
        border: '4px solid rgba(255,255,255,0.15)',
        borderTop: '4px solid #8ec5ff',
        borderRadius: '50%',
        animation: 'spinLoader 0.8s linear infinite',
      }}
    />
  </div>
)}
  {showPopup && (
  <div
    style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      background: 'rgba(0,0,0,0.6)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 9999,
    }}
  >
    <div
      style={{
        background: '#fff',
        padding: '40px',
        borderRadius: '20px',
        width: '90%',
        maxWidth: '450px',
        textAlign: 'center',
        boxShadow: '0 20px 60px rgba(0,0,0,0.2)',
        fontFamily: 'Arial',
      }}
    >
      <div style={{ fontSize: '50px', marginBottom: '15px' }}>
        ✅
      </div>

      <h2
        style={{
          fontSize: '32px',
          marginBottom: '12px',
          color: '#111',
        }}
      >
        Application Submitted
      </h2>

      <p
        style={{
          color: '#555',
          lineHeight: '1.6',
          marginBottom: '25px',
          fontSize: '16px',
        }}
      >
        Thank you for applying. Our team will connect with you shortly.
      </p>

    <button
  onClick={() => {
    setShowPopup(false)
    setPage('home')
    window.scrollTo(0, 0)
  }}
        style={{
          background: '#021826',
          color: '#fff',
          border: 'none',
          padding: '14px 28px',
          borderRadius: '10px',
          cursor: 'pointer',
          fontSize: '16px',
          fontWeight: '600',
        }}
      >
        Close
      </button>
    </div>
  </div>
)}
  </>
)
}
